const script=document.currentScript,SQLJS_BASE=new URL('../vendor/sqljs/',script.src).href,DATA_BASE=new URL('../../Plantillas/proyecto-final/Datos/',script.src).href,NESTED_MODULE=new URL('./s15-nested-duckdb-v1.mjs',script.src).href;
