const exact=(a,b)=>a.length===b.length&&a.every(x=>b.includes(x));
const TASKS={
 q1:{title:'Q1 · Alta por barrio',prompt:'Devuelve SOLO barrios que tengan al menos un caso de prioridad Alta.',contract:'Columnas exactas: barrio, casos_alta. No incluyas barrios con 0 casos Alta.',cols:['barrio','casos_alta'],starter:"SELECT barrio, COUNT(*) AS casos_alta\nFROM casos_src\nWHERE prioridad = 'Media'\nGROUP BY barrio;",concept:'Revisa qué condición define la población que estás contando.',counter:'Si un barrio tiene 2 Alta y 1 Media, filtrar Media responde otra pregunta.',parsons:["SELECT barrio, COUNT(*) AS casos_alta","FROM casos_src","WHERE prioridad = 'Alta'","GROUP BY barrio"]},
 q2:{title:'Q2 · Último evento temporal',prompt:'Compara el snapshot actual con el estado del evento de fecha más reciente de cada caso.',contract:'Columnas exactas: caso_id, estado_actual, ultimo_estado. El orden lo define fecha_evento; no evento_id ni el orden alfabético del estado.',cols:['caso_id','estado_actual','ultimo_estado'],starter:"SELECT c.caso_id, c.estado AS estado_actual,\n       MAX(e.estado) AS ultimo_estado\nFROM casos_src c\nLEFT JOIN eventos_src e ON e.caso_id=c.caso_id\nGROUP BY c.caso_id,c.estado;",concept:'MAX(texto) no significa último en el tiempo.',counter:'Un caso puede cerrarse y reabrirse; el último estado se determina por fecha_evento.',parsons:['WITH ultima_fecha AS (...)','MAX(fecha_evento)','JOIN eventos_src con la fecha máxima','LEFT JOIN desde casos_src']},
 q3:{title:'Q3 · Minutos de casos terminados cerrados',prompt:'Suma toda la trayectoria de los casos cuyo ÚLTIMO evento temporal es Cerrado.',contract:'Columnas exactas: caso_id, minutos_hasta_cierre. Un caso reabierto no pertenece al conjunto aunque tenga un evento Cerrado antiguo.',cols:['caso_id','minutos_hasta_cierre'],starter:"SELECT caso_id, SUM(minutos_desde_anterior) AS minutos_hasta_cierre\nFROM eventos_src\nWHERE estado='Cerrado'\nGROUP BY caso_id;",concept:'Primero define el conjunto por el último evento; después vuelve al historial y suma toda la trayectoria.',counter:'0 + 90 + 40 = 130. Sumar solo la fila Cerrado devuelve 40; incluir un caso reabierto también es incorrecto.',parsons:['identificar fecha del último evento','quedarse con último estado = Cerrado','volver a eventos_src','SUM(minutos_desde_anterior)','GROUP BY caso_id']},
 q4:{title:'Q4 · Grano tras JOIN',prompt:'Entrega total_casos, total_eventos y casos_alta sin inflar casos por la relación 1:N.',contract:'Una sola fila con columnas exactas: total_casos, total_eventos, casos_alta.',cols:['total_casos','total_eventos','casos_alta'],starter:"SELECT COUNT(*) AS total_casos,\n       COUNT(*) AS total_eventos,\n       SUM(CASE WHEN c.prioridad='Alta' THEN 1 ELSE 0 END) AS casos_alta\nFROM casos_src c\nLEFT JOIN eventos_src e ON e.caso_id=c.caso_id;",concept:'Después de un JOIN 1:N, COUNT(*) cuenta filas del resultado, no entidades.',counter:'Un caso con 3 eventos aparece 3 veces; no se convirtió en 3 casos.',parsons:['resumir antes de unir, o proteger el identificador','COUNT(DISTINCT c.caso_id)','COUNT(e.evento_id)','LEFT JOIN eventos_src e']},
 q5:{title:'Q5 · Promedio por caso',prompt:'Por tipo: cantidad de casos y promedio de minutos acumulados POR CASO; casos sin eventos valen 0.',contract:'Columnas exactas: tipo, casos, promedio_minutos. Redondea promedio_minutos a 1 decimal.',cols:['tipo','casos','promedio_minutos'],starter:"SELECT c.tipo, COUNT(*) AS casos,\n       ROUND(AVG(e.minutos_desde_anterior),1) AS promedio_minutos\nFROM casos_src c\nLEFT JOIN eventos_src e ON e.caso_id=c.caso_id\nGROUP BY c.tipo;",concept:'Vuelve primero al grano caso y recién después promedia.',counter:'Si un caso tiene 1 evento y otro 5, promediar eventos hace que el segundo pese cinco veces más.',parsons:['WITH por_caso AS (...)','COALESCE(SUM(e.minutos_desde_anterior),0)','GROUP BY c.caso_id, c.tipo','ROUND(AVG(total_minutos),1)','GROUP BY tipo']}
};
const SQL_SOLUTIONS={"q1":"<pre class=\"code\">SELECT barrio,\n       COUNT(*) AS casos_alta\nFROM casos_src\nWHERE prioridad = 'Alta'\nGROUP BY barrio;</pre><p><b>Explicación:</b> primero <code>WHERE</code> deja solo los casos Alta; después <code>GROUP BY barrio</code> forma los grupos y <code>COUNT(*)</code> cuenta dentro de cada barrio.</p>","q2":"<pre class=\"code\">WITH ultima_fecha AS (\n  SELECT caso_id,\n         MAX(fecha_evento) AS fecha_evento\n  FROM eventos_src\n  GROUP BY caso_id\n)\nSELECT c.caso_id,\n       c.estado AS estado_actual,\n       e.estado AS ultimo_estado\nFROM casos_src c\nLEFT JOIN ultima_fecha u\n  ON u.caso_id = c.caso_id\nLEFT JOIN eventos_src e\n  ON e.caso_id = u.caso_id\n AND e.fecha_evento = u.fecha_evento;</pre><p><b>Explicación:</b> <code>MAX(estado)</code> compara texto. Aquí primero encuentras la fecha más reciente de cada caso y luego recuperas el estado de esa fila.</p>","q3":"<div class=\"contract\"><b>Orden:</b> último evento → seleccionar casos → volver al historial → sumar.</div><pre class=\"code\">WITH ultima_fecha AS (\n  SELECT caso_id,\n         MAX(fecha_evento) AS fecha_evento\n  FROM eventos_src\n  GROUP BY caso_id\n),\ncerrados AS (\n  SELECT u.caso_id\n  FROM ultima_fecha u\n  JOIN eventos_src e\n    ON e.caso_id = u.caso_id\n   AND e.fecha_evento = u.fecha_evento\n  WHERE e.estado = 'Cerrado'\n)\nSELECT e.caso_id,\n       SUM(e.minutos_desde_anterior) AS minutos_hasta_cierre\nFROM eventos_src e\nJOIN cerrados c\n  ON c.caso_id = e.caso_id\nGROUP BY e.caso_id;</pre><p><b>Explicación:</b> primero decides qué casos realmente terminan Cerrado. Solo después vuelves a todo el historial de esos casos y sumas sus minutos. Un caso cerrado y luego reabierto no entra.</p>","q4":"<pre class=\"code\">SELECT COUNT(DISTINCT c.caso_id) AS total_casos,\n       COUNT(e.evento_id) AS total_eventos,\n       COUNT(DISTINCT CASE\n         WHEN c.prioridad = 'Alta' THEN c.caso_id\n       END) AS casos_alta\nFROM casos_src c\nLEFT JOIN eventos_src e\n  ON e.caso_id = c.caso_id;</pre><p><b>Explicación:</b> un JOIN 1:N repite el caso una vez por evento. <code>DISTINCT</code> evita que esas filas repetidas se conviertan en casos adicionales.</p>","q5":"<pre class=\"code\">WITH por_caso AS (\n  SELECT c.caso_id,\n         c.tipo,\n         COALESCE(SUM(e.minutos_desde_anterior), 0) AS total_minutos\n  FROM casos_src c\n  LEFT JOIN eventos_src e\n    ON e.caso_id = c.caso_id\n  GROUP BY c.caso_id, c.tipo\n)\nSELECT tipo,\n       COUNT(*) AS casos,\n       ROUND(AVG(total_minutos), 1) AS promedio_minutos\nFROM por_caso\nGROUP BY tipo;</pre><p><b>Explicación:</b> primero vuelves a una fila por caso. Después promedias casos, no eventos. <code>COALESCE(...,0)</code> hace que un caso sin eventos aporte 0 minutos.</p>"};
const STATION_GUIDES={"s0":{"hints":["Busca primero algo que puedas observar directamente en las tablas.","Un evento cuyo caso no existe es un hallazgo; explicar por qué ocurrió ya es otra pregunta.","Si la causa no está registrada en los datos, trátala como hipótesis."],"solution":"<p><b>Respuesta:</b> “Existe un evento cuyo caso no aparece en CASOS” es un hallazgo observable. “Ocurrió por una falla de sincronización” es una hipótesis sobre la causa.</p>"},"s2":{"hints":["caso_id identifica CASO y evento_id identifica EVENTO.","Un caso puede tener muchos eventos; EVENTO necesita caso_id para referenciar CASO.","agente_nombre depende de agente_id, por eso conviene separar AGENTE."],"solution":"<table><tr><th>Elemento</th><th>Respuesta</th></tr><tr><td>CASO</td><td>caso_id, fecha_creacion, tipo, prioridad, estado, barrio</td></tr><tr><td>EVENTO</td><td>evento_id, caso_id, fecha_evento, estado, minutos_desde_anterior</td></tr><tr><td>PK</td><td>CASO.caso_id y EVENTO.evento_id</td></tr><tr><td>FK</td><td>EVENTO.caso_id → CASO.caso_id</td></tr><tr><td>Cardinalidad</td><td>1:N</td></tr></table><p><b>3FN:</b> CASO(caso_id,barrio), EVENTO(evento_id,caso_id,fecha_evento,agente_id), AGENTE(agente_id,agente_nombre).</p>"},"s3":{"hints":["Los identificadores que no pueden repetirse necesitan PRIMARY KEY; los campos obligatorios necesitan NOT NULL.","EVENTO pertenece a CASO: protege evento.caso_id con una FOREIGN KEY.","minutos puede ser 0, pero no negativo: el CHECK correcto usa >= 0."],"solution":"<pre class=\"code\">CREATE TABLE caso(\n  caso_id INTEGER PRIMARY KEY,\n  fecha_creacion TEXT NOT NULL,\n  tipo TEXT NOT NULL,\n  prioridad TEXT NOT NULL,\n  estado TEXT NOT NULL,\n  barrio TEXT NOT NULL\n);\n\nCREATE TABLE evento(\n  evento_id TEXT PRIMARY KEY,\n  caso_id INTEGER NOT NULL,\n  fecha_evento TEXT NOT NULL,\n  estado TEXT NOT NULL,\n  minutos_desde_anterior INTEGER NOT NULL\n    CHECK (minutos_desde_anterior >= 0),\n  FOREIGN KEY (caso_id) REFERENCES caso(caso_id)\n);</pre><p><b>Explicación:</b> PK evita duplicados; FK evita huérfanos; NOT NULL exige datos obligatorios; CHECK acepta 0 y rechaza negativos. Los INSERT de prueba y Escalado ya están preparados: aquí solo debes editar el DDL.</p>"},"s4":{"hints":["Lo que necesitas cada vez que abres el caso puede vivir dentro del documento.","Si el ciudadano tiene vida propia, guarda su ID dentro y mantén el perfil aparte; el historial que crece sin límite también conviene fuera.","Para el caso, /caso_id dirige consultas a un caso concreto; estado tendría pocos valores muy repetidos."],"solution":"<table><tr><th>Decisión</th><th>Respuesta</th></tr><tr><td>Embeber</td><td>estado actual, evidencias[]</td></tr><tr><td>Referencia</td><td>ciudadano_id</td></tr><tr><td>Fuera</td><td>historial de eventos, perfil ciudadano</td></tr><tr><td>CASO</td><td>Documental</td></tr><tr><td>Libro contable</td><td>Relacional SQL</td></tr><tr><td>Cosmos DB</td><td>/caso_id</td></tr></table><p><b>Explicación:</b> junta lo que se lee junto; referencia lo que tiene ciclo de vida propio y evita que una colección ilimitada haga crecer el documento principal.</p>"},"s5":{"hints":["Si un caso tiene E01 y E02 y necesitas conservar ambos momentos, una fila por caso perdería información: el grano debe ser evento.","conteo y minutos son medidas; fecha, barrio, tipo, prioridad y estado son dimensiones.","menos de 30 s → streaming; actualización nocturna → batch; cargar crudo y transformar dentro → ELT."],"solution":"<table><tr><th>Elemento</th><th>Respuesta</th></tr><tr><td>Grano</td><td>evento</td></tr><tr><td>Medidas</td><td>conteo de eventos, minutos</td></tr><tr><td>Dimensiones</td><td>fecha, barrio, tipo, prioridad, estado</td></tr><tr><td>OLTP</td><td>casos/eventos actuales</td></tr><tr><td>OLAP</td><td>fact_evento histórico</td></tr><tr><td>&lt;30 s</td><td>Streaming</td></tr><tr><td>cada noche</td><td>Batch</td></tr><tr><td>cargar crudo y transformar dentro</td><td>ELT</td></tr></table><p><b>Explicación:</b> primero define qué representa una fila; después medidas y dimensiones; al final decide cómo y cuándo mover los datos.</p>"},"s6":{"hints":["El filtro presente en 100% de las consultas debe guiar la partición.","Después de fecha, el filtro más frecuente es barrio.","tipo suele acompañar a barrio; caso_id no aparece en el patrón."],"solution":"<pre class=\"code\">PARTITION BY DATE(fecha_evento)\nCLUSTER BY barrio, tipo</pre><p><b>Explicación:</b> fecha recorta por periodo; barrio es el filtro dominante dentro de ese periodo y tipo el segundo acompañante.</p>"},"s7":{"hints":["caso_id y estado describen al caso y permanecen en la raíz.","tipo, url y texto describen cada evidencia; viven dentro de evidencias[]. JSON conserva flexibilidad y Parquet sirve para analítica columnar.","UNNEST(c.evidencias) crea una fila por evidencia; conserva caso_id para mantener el vínculo con el caso."],"solution":"<table><tr><th>Zona</th><th>Respuesta</th></tr><tr><td>Raíz</td><td>caso_id, estado</td></tr><tr><td>evidencias[]</td><td>tipo, url, texto</td></tr><tr><td>Landing flexible</td><td>JSON</td></tr><tr><td>Analítica columnar</td><td>Parquet</td></tr></table><pre class=\"code\">SELECT c.caso_id,\n       ev.tipo\nFROM `proyecto.dataset.casos_nested` AS c\nCROSS JOIN UNNEST(c.evidencias) AS ev;</pre><p><b>Explicación:</b> antes de UNNEST una fila representa un caso; después, una fila representa una evidencia del caso.</p>"},"boss":{"hints":["cantidad e importe pertenecen a cada línea; costo_envio pertenece al pedido.","El patrón de práctica prioriza fecha, luego categoría y después canal.","Para items[] conserva pedido_id al hacer UNNEST; en Azure piensa primero en la necesidad y luego en la familia de servicio."],"solution":"<table><tr><th>Decisión</th><th>Respuesta</th></tr><tr><td>Diseño analítico</td><td>dos hechos: línea y pedido</td></tr><tr><td>Grano ventas</td><td>línea de pedido</td></tr><tr><td>Medidas</td><td>cantidad, importe</td></tr><tr><td>Partición</td><td>fecha_pedido</td></tr><tr><td>Clustering práctica</td><td>categoria, canal</td></tr></table><pre class=\"code\">SELECT p.pedido_id,\n       i.categoria,\n       i.cantidad\nFROM `proyecto.dataset.pedidos_nested` AS p\nCROSS JOIN UNNEST(p.items) AS i;</pre><p><b>Azure:</b> objetos → Blob/ADLS Gen2; documento operacional → Cosmos DB; lakehouse/analítica → Fabric/Databricks; BI → Power BI.</p>"}};
