function dbFor(d){const db=new SQL.Database();db.run("CREATE TABLE casos_src(caso_id INTEGER,fecha_creacion TEXT,ciudadano_id TEXT,tipo TEXT,prioridad TEXT,estado TEXT,canal TEXT,barrio TEXT);CREATE TABLE eventos_src(evento_id TEXT,caso_id INTEGER,fecha_evento TEXT,estado TEXT,agente_id TEXT,minutos_desde_anterior INTEGER);");let s=db.prepare('INSERT INTO casos_src VALUES(?,?,?,?,?,?,?,?)');for(const r of d.casos)s.run([+r.caso_id,r.fecha_creacion,r.ciudadano_id||null,r.tipo||null,r.prioridad,r.estado,r.canal||null,r.barrio]);s.free();s=db.prepare('INSERT INTO eventos_src VALUES(?,?,?,?,?,?)');for(const r of d.eventos)s.run([r.evento_id,+r.caso_id,r.fecha_evento,r.estado,r.agente_id||null,+r.minutos_desde_anterior]);s.free();return db}
function diagDb(){const db=new SQL.Database();db.run("CREATE TABLE casos_dirty(caso_id INTEGER,fecha_creacion TEXT,ciudadano_id TEXT,tipo TEXT,prioridad TEXT,estado TEXT,canal TEXT,barrio TEXT);CREATE TABLE eventos_dirty(evento_id TEXT,caso_id INTEGER,fecha_evento TEXT,estado TEXT,agente_id TEXT,minutos_desde_anterior INTEGER);");let s=db.prepare('INSERT INTO casos_dirty VALUES(?,?,?,?,?,?,?,?)');for(const r of dirty.casos)s.run([+r.caso_id,r.fecha_creacion,r.ciudadano_id||null,r.tipo||null,r.prioridad,r.estado,r.canal||null,r.barrio]);s.free();s=db.prepare('INSERT INTO eventos_dirty VALUES(?,?,?,?,?,?)');for(const r of dirty.eventos)s.run([r.evento_id,+r.caso_id,r.fecha_evento,r.estado,r.agente_id||null,+r.minutos_desde_anterior]);s.free();return db}
function execute(db,sql){const r=db.exec(sql);return r.length?{cols:r[0].columns,rows:r[0].values}:{cols:[],rows:[]}}
const nv=v=>typeof v==='number'?Math.round(v*1e6)/1e6:v;
function normalized(cols,rows){return rows.map(r=>Object.fromEntries(cols.map((c,i)=>[c,nv(r[i])]))).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))}
function latest(d){const m=new Map;for(const e of d.eventos){const k=String(e.caso_id),p=m.get(k);if(!p||String(e.fecha_evento)>String(p.fecha_evento))m.set(k,e)}return m}
function expected(id,d){if(id==='q1'){const m={};for(const c of d.casos)if(c.prioridad==='Alta')m[c.barrio]=(m[c.barrio]||0)+1;return Object.entries(m).map(([barrio,n])=>({barrio,casos_alta:n}))}if(id==='q2'){const l=latest(d);return d.casos.map(c=>({caso_id:+c.caso_id,estado_actual:c.estado,ultimo_estado:l.get(String(c.caso_id))?.estado??null}))}if(id==='q3'){const l=latest(d),closed=new Set([...l].filter(([,e])=>e.estado==='Cerrado').map(([k])=>k)),sum={};for(const e of d.eventos)if(closed.has(String(e.caso_id)))sum[e.caso_id]=(sum[e.caso_id]||0)+(+e.minutos_desde_anterior||0);return Object.entries(sum).map(([caso_id,n])=>({caso_id:+caso_id,minutos_hasta_cierre:n}))}if(id==='q4')return[{total_casos:d.casos.length,total_eventos:d.eventos.length,casos_alta:d.casos.filter(c=>c.prioridad==='Alta').length}];if(id==='q5'){const mins={};for(const c of d.casos)mins[c.caso_id]=0;for(const e of d.eventos)mins[e.caso_id]=(mins[e.caso_id]||0)+(+e.minutos_desde_anterior||0);const by={};for(const c of d.casos)(by[c.tipo]??=[]).push(mins[c.caso_id]||0);return Object.entries(by).map(([tipo,x])=>({tipo,casos:x.length,promedio_minutos:Math.round(x.reduce((a,b)=>a+b,0)/x.length*10)/10}))}return[]}
function diagnoseResult(id,r,d){const want=TASKS[id].cols;if(JSON.stringify(r.cols)!==JSON.stringify(want))return{ok:false,reason:'columnas: se esperaban '+want.join(', ')+' en ese orden'};const ok=JSON.stringify(normalized(r.cols,r.rows))===JSON.stringify(expected(id,d).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b))));return{ok,reason:ok?'':'valores o grano no coinciden con la pregunta'}}function same(id,r,d){return diagnoseResult(id,r,d).ok}
function readonly(q){const x=stripSql(q);return /^\s*(select|with)\b/i.test(x)&&!/(;\s*\S|\b(insert|update|delete|drop|alter|create|truncate|grant|revoke|attach|detach|pragma)\b)/i.test(x)}
function htmlTable(cols,rows){return '<table class="ptable"><thead><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,40).map(r=>'<tr>'+r.map(v=>'<td>'+(v==null?'<i>NULL</i>':esc(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function metric(a){return a.map(([k,v])=>'<div class="metric"><b>'+esc(v)+'</b><span>'+esc(k)+'</span></div>').join('')}
function preview(name){$$('#dataTabs button').forEach(b=>b.classList.toggle('active',b.dataset.dataset===name));if(name==='evidencias'){const docs=base.evidencias,items=docs.flatMap(d=>d.evidencias||[]);$('#profile').innerHTML=metric([['documentos',docs.length],['evidencias',items.length],['tipos',new Set(items.map(x=>x.tipo)).size],['máx/caso',Math.max(...docs.map(d=>(d.evidencias||[]).length),0)]]);$('#preview').innerHTML='<table class="ptable"><thead><tr><th>caso_id</th><th>n</th><th>tipos</th></tr></thead><tbody>'+docs.map(d=>'<tr><td>'+d.caso_id+'</td><td>'+(d.evidencias||[]).length+'</td><td>'+esc((d.evidencias||[]).map(x=>x.tipo).join(', '))+'</td></tr>').join('')+'</tbody></table>';return}const rows=base[name],cols=Object.keys(rows[0]||{});$('#profile').innerHTML=metric([['filas',rows.length],['columnas',cols.length],['IDs',new Set(rows.map(r=>r[cols[0]])).size],['vacíos',rows.reduce((n,r)=>n+cols.filter(c=>!r[c]).length,0)]]);$('#preview').innerHTML=htmlTable(cols,rows.slice(0,20).map(r=>cols.map(c=>r[c])))}

function renderSql(){const root=$('#sqlTasks');root.innerHTML='';for(const [id,t] of Object.entries(TASKS)){const a=document.createElement('article'),h=state.hints[id]||0,open=!!state.solutionOpen[id];a.className='sqltask';a.innerHTML='<header><h3>'+esc(t.title)+'</h3><p class="muted">'+esc(t.prompt)+'</p><div class="contract"><b>Contrato:</b> '+esc(t.contract)+'</div></header><div class="sqlbody"><div><textarea class="code" id="'+id+'">'+esc(state.queries[id])+'</textarea><div class="actions"><button class="btn dark" data-run="'+id+'">Probar</button><button class="btn alt" data-hint="'+id+'" '+(h>=3?'disabled':'')+'>'+(h>=3?'3/3 pistas vistas':'Pista '+(h+1)+'/3')+'</button><button class="btn yellow" data-solution="'+id+'" '+(h<3?'disabled':'')+'>'+(open?'Ocultar solución':'Ver solución')+'</button><button class="btn alt" data-reset="'+id+'">Restaurar bug</button></div><div class="locked-note">'+(h<3?'La solución se habilita después de mostrar las 3 pistas.':'Ya viste 3/3 pistas: puedes abrir la solución explicada.')+'</div><div id="status-'+id+'" class="feedback"></div><div id="solution-'+id+'" class="guided-answer" '+(open?'':'hidden')+'>'+SQL_SOLUTIONS[id]+'</div></div><div id="result-'+id+'" class="result"><div class="muted pad">El resultado mostrado será siempre el escenario base.</div></div></div>';root.appendChild(a)}}
