function renderModel(){const m=map(MODEL_FIELDS),used=new Set([...state.model.entities.caso,...state.model.entities.evento]);tiles('#modelPalette',MODEL_FIELDS.filter(([id])=>!used.has(id)),'model');for(const ent of ['caso','evento'])$('#entity-'+ent).innerHTML=state.model.entities[ent].map(id=>'<button type="button" class="tile'+(state.model.pk[ent]===id?' selected':'')+'" data-model-field="'+esc(id)+'" data-entity="'+ent+'">'+esc(m.get(id)||id)+(state.model.pk[ent]===id?' · PK':'')+'<span class="remove" data-remove="model|'+ent+'|'+esc(id)+'">×</span></button>').join('');$('#pkCaseSelect').value=state.model.pk.caso||'';$('#pkEventSelect').value=state.model.pk.evento||'';$('#fkSelect').value=state.model.fkChoice||'';$('#cardinalitySelect').value=state.model.cardinality||'';$('#fkView').className='feedback '+(state.model.fk?'ok':'');$('#fkView').textContent=state.model.fk?'Relación registrada: EVENTO.caso_id referencia CASO.caso_id.':'Selecciona FK y cardinalidad de forma explícita.'}
function renderNorm(){const m=map(NORM_FIELDS),used=new Set([...state.norm.caso,...state.norm.evento,...state.norm.agente]);tiles('#normPalette',NORM_FIELDS.filter(([id])=>!used.has(id)),'norm');for(const z of ['caso','evento','agente'])$('#norm-'+z).innerHTML=placed('norm',z,state.norm[z],m)}
function renderDoc(){const m=map(DOC_TOKENS),used=new Set([...state.doc.embed,...state.doc.refid,...state.doc.outside]);tiles('#docPalette',DOC_TOKENS.filter(([id])=>!used.has(id)),'doc');for(const z of ['embed','refid','outside'])$('#doc-'+z).innerHTML=placed('doc',z,state.doc[z],m);$('#docStoreCase').value=state.doc.storeCase;$('#docStoreLedger').value=state.doc.storeLedger;$('#docPartitionKey').value=state.doc.partitionKey}
function renderDw(){const m=map(DW_TOKENS),used=new Set([...state.dw.grain,...state.dw.measure,...state.dw.dimension]);tiles('#dwPalette',DW_TOKENS.filter(([id])=>!used.has(id)),'dw');for(const z of ['grain','measure','dimension'])$('#dw-'+z).innerHTML=placed('dw',z,state.dw[z],m);const pm=map(PIPE_TOKENS),u=new Set([...state.pipe.oltp,...state.pipe.olap]);tiles('#pipelinePalette',PIPE_TOKENS.filter(([id])=>!u.has(id)),'pipe');for(const z of ['oltp','olap'])$('#pipe-'+z).innerHTML=placed('pipe',z,state.pipe[z],pm);$('#eventLatency').value=state.pipe.eventLatency;$('#dimLatency').value=state.pipe.dimLatency;$('#transformMode').value=state.pipe.transformMode}
function bqNumbers(){const baseTb=36.5,pre=state.bq.partition.length===1&&state.bq.partition[0]==='fecha_evento'?baseTb*31/365:baseTb;let post=pre;const filters=new Set(['barrio','tipo']);if(state.bq.cluster.length&&filters.has(state.bq.cluster[0])){post*=.42;if(state.bq.cluster[1]&&filters.has(state.bq.cluster[1]))post*=.55}return{pre,post}}
function renderBq(){const m=map(BQ_TOKENS),used=new Set([...state.bq.partition,...state.bq.cluster]);tiles('#bqPalette',BQ_TOKENS.filter(([id])=>!used.has(id)),'bq');$('#bq-partition').innerHTML=placed('bq','partition',state.bq.partition,m);$('#bq-cluster').innerHTML=placed('bq','cluster',state.bq.cluster,m);const x=bqNumbers(),fmt=t=>t>=1?t.toFixed(2)+' TB':Math.round(t*1024)+' GB';$('#bqPreBytes').textContent=fmt(x.pre);$('#bqPostBytes').textContent=fmt(x.post);$('#bqBar').style.width=Math.min(100,x.post/36.5*100)+'%';$('#bqExplain').textContent=state.bq.partition.length===1&&state.bq.partition[0]==='fecha_evento'?'La estimación previa descuenta la partición. El valor posterior simula poda de bloques solo cuando el prefijo de clustering participa en el filtro.':'Sin una partición temporal válida, el territorio completo sigue siendo candidato.'}
function renderNested(){const m=map(NESTED_TOKENS),used=new Set([...state.nested.root,...state.nested.array]);tiles('#nestedPalette',NESTED_TOKENS.filter(([id])=>!used.has(id)),'nested');for(const z of ['root','array'])$('#nested-'+z).innerHTML=placed('nested',z,state.nested[z],m);const fm=map(FORMAT_TOKENS),u=new Set([...state.format.landing,...state.format.analytics]);tiles('#formatPalette',FORMAT_TOKENS.filter(([id])=>!u.has(id)),'format');for(const z of ['landing','analytics'])$('#format-'+z).innerHTML=placed('format',z,state.format[z],fm);$('#unnestQuery').value=state.unnestQuery}
function renderBoss(){const dm=map(BOSS_DW),u=new Set([...state.boss.grain,...state.boss.measure]);tiles('#bossDwPalette',BOSS_DW.filter(([id])=>!u.has(id)),'bossdw');for(const z of ['grain','measure'])$('#boss-'+z).innerHTML=placed('bossdw',z,state.boss[z],dm);const bm=map(BOSS_BQ),v=new Set([...state.boss.partition,...state.boss.cluster]);tiles('#bossBqPalette',BOSS_BQ.filter(([id])=>!v.has(id)),'bossbq');for(const z of ['partition','cluster'])$('#boss-'+z).innerHTML=placed('bossbq',z,state.boss[z],bm);$('#bossStrategy').value=state.boss.strategy;$('#bossUnnest').value=state.boss.unnestQuery;$('#az-object').value=state.boss.azure.object_files;$('#az-document').value=state.boss.azure.operational_document;$('#az-lakehouse').value=state.boss.azure.lakehouse_analytics;$('#az-bi').value=state.boss.azure.bi_consumption;renderBossVariant()}
function renderBossVariant(){const e=$('#bossVariant');if(!bossVariant){e.textContent='Preparando workload…';return}e.innerHTML='<b>Workload asignado:</b> '+esc(bossVariant.description)+(bossVariant.sample?'<br><b>Muestra:</b> '+esc(bossVariant.sample):'')+'<br><small>'+esc(bossVariant.note||'Elige partición y clustering a partir de estas frecuencias.')+'</small>'}
function renderMutation(){const mm=map(MUTANTS);$('#mutants').innerHTML=MUTANTS.map(([id,l])=>'<button type="button" class="tile'+(selectedMutant===id?' selected':'')+'" data-kind="mutant" data-id="'+id+'"><b>Mutante</b><br>'+esc(l)+'</button>').join('');const code=$('#mutantCode'),probe=$('#mutationProbe'),box=$('#mutationState');if(!selectedMutant){code.textContent='Selecciona un mutante.';probe.value=state.mutationProbe||'';box.textContent='Escribe una prueba que haga comportarse distinto al esquema correcto y al mutante.';return}code.textContent=MUTANT_DDL[selectedMutant]||'';const saved=state.mutation[selectedMutant];probe.value=saved?.probe||state.mutationProbe||'';if(saved?.correct&&saved?.mutant){const verdict=MODE==='practica'?(saved.pass?' · diferencia diagnóstica válida':' · todavía no delata este mutante'):'';box.className='feedback '+(MODE==='practica'?(saved.pass?'ok':'warn'):'warn');box.innerHTML='<div class="mutation-outcomes"><div><b>Esquema correcto</b>'+esc(saved.correct)+'</div><div><b>Mutante</b>'+esc(saved.mutant)+'</div></div><small>En evaluación se muestran los dos resultados, no la respuesta esperada'+verdict+'.</small>'}else box.textContent='Ejecuta tu INSERT contra ambos esquemas.'}
function currentScores(){return{sql:sqlScore(),model:modelScore(),ddl:ddlScore(),doc:docScore(),dw:dwScore(),bq:bqScore(),nested:nestedScore()}}
const MAX={sql:15,model:12,ddl:10,doc:10,dw:13,bq:10,nested:10};
function displayScores(){let total=0,live=null;if(MODE==='practica')live=currentScores();for(const [k,mx] of Object.entries(MAX)){const shown=MODE==='practica'?live[k]:(state.checked[k]?state.checkedScore[k]:'—');const e=$('#score-'+k);if(e&&String(e.textContent)!==String(shown))e.textContent=shown;const n=shown==='—'?0:+shown;total+=n;document.querySelector('[data-nav="'+k+'"]')?.classList.toggle('done',shown!=='—'&&Math.abs(n-mx)<1e-9)}$('#masteryScore').textContent=MODE==='practica'?Math.round(Object.values(live).reduce((a,b)=>a+b,0)*10)/10:(Object.keys(state.checked).length?Math.round(total*10)/10:'—');$('#finalMastery').textContent=$('#masteryScore').textContent}
function canCheck(k){if(MODE==='practica')return true;const n=state.checked[k]||0;if(n>=MAX_CHECKS){status('Esta estación ya usó sus 3 comprobaciones de evaluación. Puedes seguir editando, pero no se revela otro puntaje local.','warn');return false}state.checked[k]=n+1;return true}
function fb(sel,score,max,fail=[]){const e=$(sel);if(!e)return;const station=String(sel).replace(/^#fb-/,'');e.className='feedback '+(fail.length?'warn':'ok');e.innerHTML='<b>'+score+'/'+max+'</b>'+(fail.length?'<ul>'+fail.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':' · estación completa.')+(MODE==='evaluacion'?'<div class="attempt-note">Comprobación '+Math.min(state.checked[station]||0,MAX_CHECKS)+' / '+MAX_CHECKS+'</div>':'')}
async function runQ(id,show=true){save();if(MODE==='evaluacion'){const n=state.queryAttempts[id]||0;if(n>=MAX_SQL_ATTEMPTS){$('#status-'+id).className='feedback warn';$('#status-'+id).textContent='Ya usaste 3 pruebas de esta consulta en modo evaluación.';return state.queryChecks[id]?.pass||0}state.queryAttempts[id]=n+1}let n=0,error='',baseResult=null,details=[];const sql=state.queries[id];if(!readonly(sql))error='Solo SELECT/WITH de lectura. Los comentarios al inicio sí son válidos.';else for(const v of variants(base)){const db=dbFor(v.data);try{const r=execute(db,stripSql(sql));if(v.name==='base')baseResult=r;const diag=diagnoseResult(id,r,v.data),ok=diag.ok;if(ok)n++;details.push({name:v.name,ok,reason:diag.reason})}catch(e){error=String(e.message||e);details.push({name:v.name,ok:false})}finally{db.close()}}state.queryChecks[id]={pass:n,total:4,details};save();if(show){const e=$('#status-'+id);e.className='feedback '+(n===4?'ok':'warn');e.innerHTML='<b>'+n+'/4 escenarios visibles.</b> '+(error?esc(error):details.map(x=>(x.ok?'✓ ':'× ')+esc(x.name)+(x.ok?'':' — '+esc(x.reason||'revisa la consulta'))).join(' · '));if(baseResult)$('#result-'+id).innerHTML=htmlTable(baseResult.cols,baseResult.rows)}displayScores();return n}
async function runAllQ(){const btn=$('#runAllSql');if(btn){btn.disabled=true;btn.textContent='Probando…'}try{for(const id of Object.keys(TASKS)){await runQ(id,false);await new Promise(r=>setTimeout(r,0))}}finally{if(btn){btn.disabled=false;btn.textContent='Probar las 5 consultas'}}if(!canCheck('sql'))return;const s=sqlScore();state.checkedScore.sql=s;save();fb('#fb-sql',s,15,s<15?['Alguna consulta no satisface el contrato en todos los escenarios visibles.']:[]);displayScores()}
function hint(id){const n=Math.min(3,(state.hints[id]||0)+1);state.hints[id]=n;save();const t=TASKS[id],e=$('#status-'+id);e.className='feedback warn';e.innerHTML=n===1?'<b>Pista 1/3 · Qué debes pensar:</b> '+esc(t.concept):n===2?'<b>Pista 2/3 · Ejemplo o contraejemplo:</b> '+esc(t.counter):'<b>Pista 3/3 · Orden para resolver:</b><div class="parsons">'+t.parsons.map(x=>'<code>'+esc(x)+'</code>').join('')+'</div>';const s=document.querySelector('[data-solution="'+id+'"]'),h=document.querySelector('[data-hint="'+id+'"]');if(s)s.disabled=n<3;if(h){h.textContent=n>=3?'3/3 pistas vistas':'Pista '+(n+1)+'/3';h.disabled=n>=3}const note=s?.parentElement?.nextElementSibling;if(note&&note.classList.contains('locked-note'))note.textContent=n<3?'La solución se habilita después de mostrar las 3 pistas.':'Ya viste 3/3 pistas: puedes abrir la solución explicada.'}
function toggleSqlSolution(id){if((state.hints[id]||0)<3)return;state.solutionOpen[id]=!state.solutionOpen[id];save();const box=$('#solution-'+id),btn=document.querySelector('[data-solution="'+id+'"]');if(box)box.hidden=!state.solutionOpen[id];if(btn)btn.textContent=state.solutionOpen[id]?'Ocultar solución':'Ver solución'}
const sqlScore=()=>Math.round(Object.values(state.queryChecks).reduce((n,x)=>n+3*(Math.min(x.pass||0,4)/4),0)*10)/10;

function modelScore(render=false){const f=[];let s=0;const caso=['caso.caso_id','caso.fecha_creacion','caso.tipo','caso.prioridad','caso.estado','caso.barrio'],evento=['evento.evento_id','evento.caso_id','evento.fecha_evento','evento.estado','evento.minutos_desde_anterior'];if(exact(state.model.entities.caso,caso))s+=2;else f.push('CASO debe contener exactamente sus seis atributos.');if(exact(state.model.entities.evento,evento))s+=2;else f.push('EVENTO debe contener exactamente sus cinco atributos.');if(state.model.pk.caso==='caso.caso_id'&&state.model.pk.evento==='evento.evento_id')s+=2;else f.push('Revisa las dos PK.');if(state.model.fk==='evento.caso_id->caso.caso_id'&&state.model.cardinality==='1:N')s+=2;else f.push('Revisa FK y cardinalidad.');if(exact(state.norm.caso,['caso.caso_id','caso.barrio'])&&exact(state.norm.evento,['evento.evento_id','evento.caso_id','evento.fecha_evento','evento.agente_id']))s+=2;else f.push('Revisa la descomposición CASO/EVENTO.');if(exact(state.norm.agente,['agente.agente_id','agente.agente_nombre']))s+=2;else f.push('AGENTE debe separar id y nombre.');if(render)fb('#fb-model',s,12,f);return s}
function ddlStarter(){return "CREATE TABLE caso(\n  caso_id INTEGER,\n  fecha_creacion TEXT,\n  tipo TEXT,\n  prioridad TEXT,\n  estado TEXT,\n  barrio TEXT\n);\nCREATE TABLE evento(\n  evento_id TEXT,\n  caso_id INTEGER,\n  fecha_evento TEXT,\n  estado TEXT,\n  minutos_desde_anterior INTEGER\n);"}
function runDdl(reveal=false){save();if(reveal&&!canCheck('ddl'))return;if(!reveal&&MODE==='evaluacion'){if((state.ddlRuns||0)>=MAX_CHECKS){status('Ya usaste 3 ejecuciones de ataques DDL en modo evaluación. Usa Comprobar cuando quieras registrar el estado de la estación.','warn');return}state.ddlRuns=(state.ddlRuns||0)+1}const o={};let db;try{db=new SQL.Database();db.run('PRAGMA foreign_keys=ON;');db.run(state.ddl);const columns=t=>new Set((db.exec('PRAGMA table_info('+t+')')[0]?.values||[]).map(r=>String(r[1]))),caseCols=columns('caso'),eventCols=columns('evento');const insertCase=(id,tipo='Ruido',prioridad='Alta',estado='Abierto',barrio='Prueba')=>{const cols=['caso_id','fecha_creacion','tipo','prioridad','estado','barrio'],vals=[id,'2026-09-01',tipo,prioridad,estado,barrio];if(caseCols.has('ciudadano_id')){cols.splice(2,0,'ciudadano_id');vals.splice(2,0,'C'+id)}if(caseCols.has('canal')){cols.push('canal');vals.push('Web')}db.run('INSERT INTO caso('+cols.join(',')+') VALUES('+cols.map(()=>'?').join(',')+')',vals)};const insertEvent=(eid,cid,fecha,estado,minutos)=>{const cols=['evento_id','caso_id','fecha_evento','estado','minutos_desde_anterior'],vals=[eid,cid,fecha,estado,minutos];if(eventCols.has('agente_id')){cols.splice(4,0,'agente_id');vals.splice(4,0,'A01')}db.run('INSERT INTO evento('+cols.join(',')+') VALUES('+cols.map(()=>'?').join(',')+')',vals)};const rejects=fn=>{try{fn();return false}catch{return true}},accepts=fn=>{try{fn();return true}catch{return false}};insertCase(9001);insertEvent(9101,9001,'2026-09-01 08:00','Abierto',0);o.dup_case=rejects(()=>insertCase(9001));o.dup_event=rejects(()=>insertEvent(9101,9001,'2026-09-01 08:10','Abierto',10));o.orphan=rejects(()=>insertEvent(9199,9999,'2026-09-01 09:00','Abierto',0));o.null_tipo=rejects(()=>insertCase(9002,null,'Media','Abierto','Prueba'));o.neg=rejects(()=>insertEvent(9200,9001,'2026-09-01 10:00','Abierto',-1));o.null_minutes=rejects(()=>insertEvent(9201,9001,'2026-09-01 11:00','Abierto',null));o.zero_valid=accepts(()=>insertEvent(9202,9001,'2026-09-01 12:00','Abierto',0))}catch(e){o.error=String(e.message||e)}finally{try{db?.close()}catch{}}state.ddlChecks=o;if(reveal&&String(state.domainMigration||'').trim())runDomainMigration();if(reveal)state.checkedScore.ddl=ddlScore();save();renderDdlTests();if(reveal)fb('#fb-ddl',state.checkedScore.ddl,10,o.error?['El DDL no ejecutó; revisa el mensaje de sintaxis.']:state.checkedScore.ddl<10?['Alguna restricción, prueba mutante o estrategia de evolución necesita revisión.']:[]);displayScores()}
function runDomainMigration(){save();const sql=stripSql(state.domainMigration||'');const box=$('#domainMigrationFeedback');const out={beforeFails:false,afterPass:false,pass:false};if(!/^insert\s+(?:or\s+ignore\s+)?into\s+estado_catalogo\b/i.test(sql)||/(;\s*\S|\b(drop|alter|delete|update|create|attach|pragma)\b)/i.test(sql)){box.className='feedback warn';box.textContent='Usa una única sentencia INSERT sobre estado_catalogo para representar la migración.';state.domainMigrationResult=out;save();return}let db;try{db=new SQL.Database();db.run('PRAGMA foreign_keys=ON;');db.run("CREATE TABLE estado_catalogo(estado TEXT PRIMARY KEY);CREATE TABLE caso_estado(caso_id INTEGER PRIMARY KEY,estado TEXT NOT NULL,FOREIGN KEY(estado) REFERENCES estado_catalogo(estado));INSERT INTO estado_catalogo VALUES('Abierto'),('Cerrado'),('En_proceso');");try{db.run("INSERT INTO caso_estado VALUES(1,'Escalado')")}catch{out.beforeFails=true}db.run(sql);try{db.run("INSERT INTO caso_estado VALUES(2,'Escalado')");out.afterPass=true}catch{}out.pass=out.beforeFails&&out.afterPass}catch(e){out.error=String(e.message||e)}finally{try{db?.close()}catch{}}state.domainMigrationResult=out;save();box.className='feedback '+(out.pass?'ok':'warn');box.textContent=out.error?'No se pudo ejecutar la migración: '+out.error:(out.pass?'Antes: rechazado · después de migrar: aceptado.':'La prueba en dos tiempos todavía no demuestra una evolución controlada.');displayScores()}
function renderDdlTests(){const a=[['dup_case','PK caso'],['dup_event','PK evento'],['orphan','FK huérfano'],['null_tipo','tipo NOT NULL'],['neg','minutos negativos'],['null_minutes','minutos NULL'],['zero_valid','minutos = 0 sigue válido']];$('#ddlSyntax').className='feedback '+(state.ddlChecks.error?'bad':'');$('#ddlSyntax').textContent=state.ddlChecks.error?'Tu DDL no se ejecutó: '+state.ddlChecks.error:(Object.keys(state.ddlChecks).length?'DDL ejecutado; revisa las pruebas de comportamiento.':'');$('#ddlTests').innerHTML=a.map(([k,l])=>'<span class="pill '+(state.ddlChecks[k]?'ok':'bad')+'">'+(state.ddlChecks[k]?'✓':'×')+' '+l+'</span>').join('')}
function ddlScore(){const core=['dup_case','dup_event','orphan','null_tipo','neg','null_minutes'].filter(k=>state.ddlChecks[k]).length,minutesRule=state.ddlChecks.neg&&state.ddlChecks.null_minutes&&state.ddlChecks.zero_valid?1:0,mut=Object.values(state.mutation).filter(x=>x&&x.pass).length,evo=state.domainMigrationResult?.pass?1:0;return Math.round(Math.min(10,core+minutesRule+mut*2/3+evo)*10)/10}
function docScore(render=false){const checks=[exact(state.doc.embed,['snapshot_estado','evidencias']),exact(state.doc.refid,['ciudadano_ref']),exact(state.doc.outside,['historial_eventos','perfil_ciudadano']),state.doc.storeCase==='document',state.doc.storeLedger==='relational',state.doc.partitionKey==='/caso_id'];const w=[2,1.5,1.5,1.5,1.5,2];let s=0;checks.forEach((x,i)=>{if(x)s+=w[i]});const f=[];if(!checks[0]||!checks[1]||!checks[2])f.push('Usa exactamente las tres zonas: contenido embebido, id de referencia dentro y recursos con ciclo propio fuera.');if(!checks[3]||!checks[4])f.push('Decide SQL/NoSQL por requisitos, no por el formato JSON.');if(!checks[5])f.push('Revisa la partition key del documento de caso.');if(render)fb('#fb-doc',s,10,f);return s}
function dwScore(render=false){let s=0,f=[];if(exact(state.dw.grain,['grain:evento']))s+=2;else f.push('El hecho debe tener un solo grano: evento.');if(exact(state.dw.measure,['measure:conteo_evento','measure:minutos']))s+=2;else f.push('Revisa las medidas y evita sobreinclusión.');if(exact(state.dw.dimension,['dimension:fecha','dimension:barrio','dimension:tipo','dimension:prioridad','dimension:estado']))s+=3;else f.push('Completa exactamente las dimensiones requeridas.');if(exact(state.pipe.oltp,['operacional']))s+=1;else f.push('Distingue OLTP.');if(exact(state.pipe.olap,['fact_evento']))s+=1;else f.push('Distingue OLAP.');if(state.pipe.eventLatency==='streaming')s+=1;else f.push('Menos de 30 s exige streaming.');if(state.pipe.dimLatency==='batch')s+=1;else f.push('Actualización nocturna puede ser batch.');if(state.pipe.transformMode==='elt')s+=2;else f.push('Cargar crudo y transformar dentro corresponde a ELT.');if(render)fb('#fb-dw',s,13,f);return s}
function bqScore(render=false){let s=0,f=[];const p=state.bq.partition,c=state.bq.cluster;if(exact(p,['fecha_evento']))s+=3;else f.push('PARTITION BY debe contener exactamente una columna alineada con el filtro temporal.');if(exact(c,['barrio','tipo']))s+=5;else f.push('El workload visible prioriza barrio y luego tipo.');if(c.length===2&&!c.includes('caso_id'))s+=1;else f.push('No agregues columnas que el workload no filtra.');const x=bqNumbers();if(x.pre<36.5&&x.post<x.pre)s+=1;else f.push('El diseño todavía no produce poda coherente en el simulador.');if(render)fb('#fb-bq',s,10,f);return s}
function nestedStructure(q){const x=stripSql(q),m=x.match(/unnest\s*\(\s*(?:([A-Za-z_]\w*)\s*\.\s*)?evidencias\s*\)\s+(?:as\s+)?([A-Za-z_]\w*)/i);if(!m)return{ok:false};const alias=m[2];return{ok:new RegExp('\\bcaso_id\\b','i').test(x)&&new RegExp('\\b'+alias+'\\s*\\.\\s*tipo\\b','i').test(x),alias}}
