async function runNested(){save();state.nested.executed=false;state.nested.execError='';const fbk=$('#unnestFeedback');try{const st=nestedStructure(state.unnestQuery);if(!st.ok)throw new Error('La consulta debe expandir la colección y conservar la clave raíz y el tipo de evidencia.');fbk.className='feedback';fbk.textContent='Preparando DuckDB-Wasm solo para esta actividad…';const engine=await ensureNestedEngine();const r=await engine.validate(state.unnestQuery);state.nested.executed=true;$('#unnestResult').innerHTML=htmlTable(r.fields,r.rows);fbk.className='feedback ok';fbk.textContent='Consulta ejecutada: el cambio de grano produjo filas de evidencia.'}catch(e){state.nested.execError=String(e.message||e);fbk.className='feedback warn';fbk.textContent='No se pudo validar todavía: '+state.nested.execError}save();displayScores()}
function nestedScore(render=false){let s=0,f=[];if(exact(state.nested.root,['caso_id','estado']))s+=2;else f.push('Revisa los campos raíz.');if(exact(state.nested.array,['e.tipo','e.url','e.texto']))s+=2;else f.push('Las fichas deben corresponder a los campos reales de evidencias.json.');if(exact(state.format.landing,['JSON']))s+=1.5;else f.push('Landing flexible: una sola elección.');if(exact(state.format.analytics,['Parquet']))s+=1.5;else f.push('Analítica columnar: una sola elección.');if(state.nested.executed&&nestedStructure(state.unnestQuery).ok)s+=3;else f.push('Ejecuta una expansión válida; los comentarios no cuentan como SQL.');s=Math.round(s*10)/10;if(render)fb('#fb-nested',s,10,f);return s}
function renderStudyGuides(){for(const [id,g] of Object.entries(STATION_GUIDES)){const sec=document.getElementById(id);if(!sec||sec.querySelector('[data-study-guide="'+id+'"]'))continue;const n=state.hints[id]||0,open=!!state.solutionOpen[id],wrap=document.createElement('div');wrap.className='study-guide card inset';wrap.dataset.studyGuide=id;wrap.innerHTML='<h3>Ayuda guiada</h3><p class="muted">La solución se desbloquea después de revisar tres pistas claras.</p><div class="actions"><button type="button" class="btn alt" data-study-hint="'+id+'" '+(n>=3?'disabled':'')+'>'+(n>=3?'3/3 pistas vistas':'Pista '+(n+1)+'/3')+'</button><button type="button" class="btn yellow" data-study-solution="'+id+'" '+(n<3?'disabled':'')+'>'+(open?'Ocultar solución':'Ver solución')+'</button></div><div id="study-hints-'+id+'" class="feedback"></div><div id="study-solution-'+id+'" class="guided-answer" '+(open?'':'hidden')+'>'+g.solution+'</div>';sec.appendChild(wrap);renderStudyHintText(id)}}
