function prepareSolvedDdl(){const dm=$('#domainMigration'),mp=$('#mutationProbe');if(dm){if(!String(state.domainMigration||'').trim())state.domainMigration="INSERT INTO estado_catalogo(estado) VALUES ('Escalado');";dm.value=state.domainMigration;dm.readOnly=true}if(mp)mp.readOnly=true}
function renderRelevant(k){if(k==='model')renderModel();if(k==='norm')renderNorm();if(k==='doc')renderDoc();if(k==='dw'||k==='pipe')renderDw();if(k==='bq')renderBq();if(k==='nested'||k==='format')renderNested();if(k==='bossdw'||k==='bossbq')renderBoss()}
function put(kind,zone,id){if(kind==='model'){for(const z of ['caso','evento'])state.model.entities[z]=state.model.entities[z].filter(x=>x!==id);state.model.entities[zone]?.push(id)}else{const targets={norm:state.norm,doc:state.doc,dw:state.dw,pipe:state.pipe,bq:state.bq,nested:state.nested,format:state.format,bossdw:state.boss,bossbq:state.boss},o=targets[kind];if(!o)return;for(const z of Object.keys(o))if(Array.isArray(o[z]))o[z]=o[z].filter(x=>x!==id);o[zone]?.push(id)}save();renderRelevant(kind);displayScores()}
function remove(kind,zone,id){const targets={model:state.model.entities,norm:state.norm,doc:state.doc,dw:state.dw,pipe:state.pipe,bq:state.bq,nested:state.nested,format:state.format,bossdw:state.boss,bossbq:state.boss},o=targets[kind];if(o?.[zone])o[zone]=o[zone].filter(x=>x!==id);if(kind==='model'){if(state.model.pk[zone]===id)state.model.pk[zone]=null;if(id==='evento.caso_id'){state.model.fk=null;state.model.fkChoice=''}}save();renderRelevant(kind);displayScores()}
function compatibleDrops(kind){if(kind==='bossdw')return $$('.drop[data-drop="boss:grain"],.drop[data-drop="boss:measure"]');if(kind==='bossbq')return $$('.drop[data-drop="boss:partition"],.drop[data-drop="boss:cluster"]');return $$('.drop[data-drop^="'+kind+':"]')}
function select(el){tap={kind:el.dataset.kind,id:el.dataset.id};$$('.tile.selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');$$('.drop.ready').forEach(x=>x.classList.remove('ready'));compatibleDrops(tap.kind).forEach(x=>x.classList.add('ready'))}
function drop(zone){if(!tap)return;const raw=zone.dataset.drop||'';let kind,z;if(raw.startsWith('boss:')){z=raw.split(':')[1];kind=['grain','measure'].includes(z)?'bossdw':'bossbq'}else [kind,z]=raw.split(':');if(kind===tap.kind)put(kind,z,tap.id);tap=null;$$('.tile.selected').forEach(x=>x.classList.remove('selected'));$$('.drop.ready').forEach(x=>x.classList.remove('ready'))}
function mutationClick(kind,id){if(kind==='mutant'){selectedMutant=id;state.mutationProbe=state.mutation[id]?.probe||MUTANT_PROBES[id]||'';save();renderMutation();const p=$('#mutationProbe');if(p)p.readOnly=true;return}}
function mutationReferenceDdl(){return "CREATE TABLE caso(caso_id INTEGER PRIMARY KEY,fecha_creacion TEXT NOT NULL,tipo TEXT NOT NULL,prioridad TEXT NOT NULL,estado TEXT NOT NULL,barrio TEXT NOT NULL);CREATE TABLE evento(evento_id INTEGER PRIMARY KEY,caso_id INTEGER NOT NULL,fecha_evento TEXT NOT NULL,estado TEXT NOT NULL,minutos_desde_anterior INTEGER NOT NULL CHECK(minutos_desde_anterior>=0),FOREIGN KEY(caso_id) REFERENCES caso(caso_id));"}
function mutationOutcome(ddl,probe,foreignKeys=true){let db;try{db=new SQL.Database();db.run('PRAGMA foreign_keys='+(foreignKeys?'ON':'OFF')+';');db.run(ddl);db.run("INSERT INTO caso(caso_id,fecha_creacion,tipo,prioridad,estado,barrio) VALUES(9001,'2026-09-01','Ruido','Alta','Abierto','Prueba')");db.run(probe);return'accept'}catch{return'reject'}finally{try{db?.close()}catch{}}}
function validMutationProbe(q){const x=stripSql(q);return /^insert\s+into\s+(caso|evento)\b/i.test(x)&&!/(;\s*\S|\b(select|with|update|delete|drop|alter|create|attach|pragma)\b)/i.test(x)}
function runMutationProbe(){if(!selectedMutant){$('#mutationState').className='feedback warn';$('#mutationState').textContent='Selecciona primero un mutante.';return}if(MODE==='evaluacion'){const n=state.mutationRuns[selectedMutant]||0;if(n>=MAX_CHECKS){$('#mutationState').className='feedback warn';$('#mutationState').textContent='Ya usaste 3 ejecuciones para este mutante en modo evaluación.';return}state.mutationRuns[selectedMutant]=n+1}const probe=$('#mutationProbe').value.trim();state.mutationProbe=probe;if(!validMutationProbe(probe)){$('#mutationState').className='feedback warn';$('#mutationState').textContent='La prueba debe ser un único INSERT sobre caso o evento, sin otra sentencia.';save();return}const isolatePk=selectedMutant==='no_case_pk',correct=mutationOutcome(mutationReferenceDdl(),probe,!isolatePk),mutant=mutationOutcome(MUTANT_DDL[selectedMutant],probe,!isolatePk),exp=MUTANT_EXPECT[selectedMutant],pass=correct===exp.correct&&mutant===exp.mutant;state.mutation[selectedMutant]={probe,correct,mutant,pass};save();renderMutation();displayScores()}
function checkStation(k){if(!canCheck(k))return;save();const fn={model:modelScore,doc:docScore,dw:dwScore,bq:bqScore,nested:nestedScore}[k],s=fn(true);state.checkedScore[k]=s;save();displayScores()}
function expectedBossCluster(){const id=String(bossVariant?.id||'practice');return id==='B'?['canal','categoria']:id==='C'?['categoria','cliente_id']:['categoria','canal']}
function bossScoreLocal(render=false){const az=state.boss.azure,checks={strategy:state.boss.strategy==='two_facts',grain:exact(state.boss.grain,['linea_pedido']),measures:exact(state.boss.measure,['cantidad','importe']),partition:exact(state.boss.partition,['fecha_pedido']),cluster:exact(state.boss.cluster,expectedBossCluster()),unnest:nestedBossStructure(state.boss.unnestQuery),az_obj:az.object_files==='blob_adls',az_doc:az.operational_document==='cosmos',az_lake:az.lakehouse_analytics==='fabric_databricks',az_bi:az.bi_consumption==='power_bi'};let s=0;if(checks.strategy)s+=3;if(checks.grain)s+=2;if(checks.measures)s+=2;if(checks.partition)s+=2;if(checks.cluster)s+=4;if(checks.unnest)s+=3;for(const k of ['az_obj','az_doc','az_lake','az_bi'])if(checks[k])s+=1;const fail=[];if(!checks.strategy)fail.push('Revisa cómo evitar duplicar costo_envio.');if(!checks.grain||!checks.measures)fail.push('Revisa grano y medidas de ventas.');if(!checks.partition||!checks.cluster)fail.push('Deriva el diseño físico del workload visible.');if(!checks.unnest)fail.push('La expansión de items debe conservar pedido_id y exponer categoría/cantidad.');if(!checks.az_obj||!checks.az_doc||!checks.az_lake||!checks.az_bi)fail.push('Revisa las equivalencias Azure.');if(render)fb('#fb-boss',s,20,fail);return s}
function updateLocalFinal(master,boss){const total=Math.round((Number(master)||0)+(Number(boss)||0));$('#finalMastery').textContent=master;$('#finalBoss').textContent=boss;$('#finalTotal').textContent=total;$('#totalScore').textContent=total;$('#score-boss').textContent=boss;return total}
function completenessBoss(){save();if(!canCheck('boss'))return;const s=bossScoreLocal(true);state.checkedScore.boss=s;save();$('#score-boss').textContent=s;const m=$('#masteryScore').textContent==='—'?0:Number($('#masteryScore').textContent)||0;updateLocalFinal(m,s)}
function nestedBossStructure(q){const x=stripSql(q),m=x.match(/unnest\s*\(\s*(?:([A-Za-z_]\w*)\s*\.\s*)?items\s*\)\s+(?:as\s+)?([A-Za-z_]\w*)/i);if(!m)return false;const a=m[2];return /\bpedido_id\b/i.test(x)&&new RegExp('\\b'+a+'\\s*\\.\\s*categoria\\b','i').test(x)&&new RegExp('\\b'+a+'\\s*\\.\\s*cantidad\\b','i').test(x)}
function flushStationTime(){if(!activeStation||!activeSince)return;const now=performance.now(),delta=Math.max(0,(now-activeSince)/1000);state.timing[activeStation]=(state.timing[activeStation]||0)+delta;activeSince=now}
function setActiveStation(id){if(id===activeStation)return;flushStationTime();activeStation=id||null;activeSince=activeStation?performance.now():0}
function initStationTiming(){if(!('IntersectionObserver'in window))return;const ratios=new Map();timingObserver=new IntersectionObserver(entries=>{for(const e of entries)ratios.set(e.target.id,e.isIntersecting?e.intersectionRatio:0);if(document.hidden){setActiveStation(null);return}let best=null,ratio=.2;for(const [id,r] of ratios)if(r>ratio){best=id;ratio=r}setActiveStation(best)},{threshold:[0,.2,.4,.6,.8]});$$('.mission').forEach(x=>timingObserver.observe(x));document.addEventListener('visibilitychange',()=>{if(document.hidden)setActiveStation(null);else{activeSince=0}});window.addEventListener('beforeunload',()=>{flushStationTime();save(true)})}
function stationSeconds(){flushStationTime();return Object.fromEntries(Object.entries(state.timing||{}).map(([k,v])=>[k,Math.round(Number(v)||0)]))}
function payload(){save();return{version:VERSION,mode:MODE,model:state.model,norm:state.norm,mutation:state.mutation,domain_migration:state.domainMigration,doc:state.doc,dw:state.dw,pipe:state.pipe,bq:state.bq,nested:{root:state.nested.root,array:state.nested.array},format:state.format,boss:{strategy:state.boss.strategy,grain:state.boss.grain,measure:state.boss.measure,partition:state.boss.partition,cluster:state.boss.cluster,unnestQuery:state.boss.unnestQuery,azure:state.boss.azure},code:{ddl:state.ddl,...state.queries,unnestQuery:state.unnestQuery},hints:state.hints,diagnostic:state.diag,station_seconds:stationSeconds(),client_at:new Date().toISOString()}}
async function submit(){save(true);const a=auth();if(!a?.token){const live=currentScores(),master=Math.round(Object.values(live).reduce((x,y)=>x+y,0)*10)/10,boss=bossScoreLocal(false),total=updateLocalFinal(master,boss);lastServer={guest:true,version:VERSION,score:total,mastery_score:master,transfer_score:boss,breakdown:{...live,boss},saved:false,feedback:'Resultado local determinístico. No se registró en servidor.'};$('#finalFeedback').textContent=lastServer.feedback;download();status('Modo invitado: resultado local '+total+'/100. Evidencia descargada; no se registró en servidor.','ok');return}status('Servidor: recalculando dominio y transferencia…','warn');try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+a.token},body:JSON.stringify(payload())}),x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.error||('HTTP '+r.status));lastServer=x;$('#totalScore').textContent=x.score;$('#finalMastery').textContent=x.mastery_score;$('#finalBoss').textContent=x.transfer_score;$('#finalTotal').textContent=x.score;$('#score-boss').textContent=x.transfer_score;$('#finalFeedback').textContent=x.feedback||'';if(x.saved===false){status('Práctica: '+x.score+'/100. No se registró como intento.','ok')}else{state.attempts.push({attempt:x.attempt,score:x.score,at:new Date().toISOString()});save();status('Intento #'+x.attempt+': '+x.score+'/100 registrado.','ok')}}catch(e){status('No se pudo registrar: '+(e.message||e),'bad')}}
async function loadBossVariant(){const a=auth();if(!a?.token){bossVariant={id:'practice',description:'100% acota fecha; 80% filtra categoría; 35% además canal; 5% cliente.',sample:'categoria=Hogar · canal=App · cliente_id=C1042',note:'Variante invitada fija: permite evaluar localmente con una solución cerrada y reproducible.'};renderBossVariant();return}try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+a.token},body:JSON.stringify({action:'init',version:VERSION})}),x=await r.json();if(r.ok&&x.variant)bossVariant=x.variant;else throw Error(x.error||'sin variante')}catch(e){bossVariant={id:'fallback',description:'100% acota fecha; 80% filtra categoría; 35% además canal; 5% cliente.',sample:'categoria=Hogar · canal=App · cliente_id=C1042',note:'No se pudo recuperar variante; recarga antes de registrar.'}}renderBossVariant()}
function download(){const b=new Blob([JSON.stringify(lastServer||payload(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='ANDESDB-S15-v7-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function renderDiagClassification(){const e=$('#diagFeedback');if(!e)return;if(!state.diag.fact&&!state.diag.hyp)return;if(state.diag.fact==='confirmed'&&state.diag.hyp==='hypothesis'){e.className='feedback ok';e.textContent='Correcto: el huérfano es un hallazgo observable; atribuirlo a una falla de sincronización sigue siendo una hipótesis.'}else if(state.diag.fact&&state.diag.hyp){e.className='feedback warn';e.textContent='Revisa la diferencia entre lo que la tabla demuestra y la explicación causal que todavía no está observada.'}}
async function runDiag(){const q=$('#diagSql').value;if(!readonly(q)){$('#diagFeedback').className='feedback warn';$('#diagFeedback').textContent='Usa SELECT/WITH de lectura.';return}const db=diagDb();try{const r=execute(db,stripSql(q));$('#diagResult').innerHTML=htmlTable(r.cols,r.rows);$('#diagFeedback').className='feedback ok';$('#diagFeedback').textContent='Consulta ejecutada sobre datos imperfectos. Ahora separa hallazgo observado de explicación hipotética.'}catch(e){$('#diagFeedback').className='feedback bad';$('#diagFeedback').textContent=String(e.message||e)}finally{db.close()}}
