 document.addEventListener('click',async e=>{const tab=e.target.closest('[data-dataset]');if(tab){preview(tab.dataset.dataset);return}const rm=e.target.closest('[data-remove]');if(rm){e.stopPropagation();const [k,z,id]=rm.dataset.remove.split('|');remove(k,z,id);return}const mf=e.target.closest('[data-model-field]');if(mf&&!e.target.closest('[data-remove]')){status('Declara las PK con los selectores explícitos de la sección Claves y relación.','warn');return}const t=e.target.closest('.tile[data-kind]');if(t){if(t.dataset.kind==='mutant'){mutationClick(t.dataset.kind,t.dataset.id);return}select(t);return}const d=e.target.closest('.drop[data-drop]');if(d&&tap){drop(d);return}const run=e.target.closest('[data-run]');if(run){await runQ(run.dataset.run);return}const h=e.target.closest('[data-hint]');if(h){hint(h.dataset.hint);return}const sol=e.target.closest('[data-solution]');if(sol){toggleSqlSolution(sol.dataset.solution);return}const sh=e.target.closest('[data-study-hint]');if(sh){studyHint(sh.dataset.studyHint);return}const ss=e.target.closest('[data-study-solution]');if(ss){toggleStudySolution(ss.dataset.studySolution);return}const reset=e.target.closest('[data-reset]');if(reset){const id=reset.dataset.reset;state.queries[id]=TASKS[id].starter;$('#'+id).value=state.queries[id];delete state.queryChecks[id];save();displayScores();return}const c=e.target.closest('[data-check]');if(c){if(c.dataset.check==='ddl'){runDdl(true);return}checkStation(c.dataset.check);return}});
